b)=>strcmp(strtolower((string)$a['name']),strtolower((string)$b['name'])));teyzaJson(200,['ok'=>true,'products'=>$products,'services'=>$services,'listings'=>$listings]);}if($action==='product'){$sid=trim((string)($_GET['seller']??''));$pid=trim((string)($_GET['product']??''));$w=teyzaLoadSellerByBusinessId($sid);if(!$w||!teyzaSellerApproved($w))teyzaJson(404,['ok'=>false,'error'=>'Seller unavailable.']);$p=teyzaFindProduct($w,$pid);if(!$p||!teyzaProductPublic($w,$p))teyzaJson(404,['ok'=>false,'error'=>'Product unavailable.']);teyzaJson(200,['ok'=>true,'product'=>teyzaPublicProduct($w,$p)]);}if($action==='service'){$sid=trim((string)($_GET['seller']??''));$id=trim((string)($_GET['service']??''));$w=teyzaLoadSellerByBusinessId($sid);if(!$w||!teyzaSellerApproved($w))teyzaJson(404,['ok'=>false,'error'=>'Seller unavailable.']);$s=svcFind($w,$id);if(!$s||!svcPublic($w,$s))teyzaJson(404,['ok'=>false,'error'=>'Service unavailable.']);teyzaJson(200,['ok'=>true,'service'=>svcView($w,$s)]);}teyzaJson(404,['ok'=>false,'error'=>'Unknown storefront action.']);